/// result ([chars] payload chars ≈ chars/4 tokens).
List<Message> _readPair(
  String callId,
  String path,
  String payloadChar, {
  int chars = 8000,
  bool isError = false,
}) => [
  _assistant(
    'reading $path',
    calls: [
      ToolCall(id: callId, name: 'read', arguments: {'path': path}),
    ],
  ),
  _result(callId, 'read', payloadChar * chars, isError: isError),
];

